-- Communication: circulars, announcements, notice board, message templates and the message log.
CREATE TABLE public.comm_circulars (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(20) NOT NULL, title VARCHAR(160) NOT NULL, audience VARCHAR(20) NOT NULL CHECK (audience IN ('Staff', 'All parents', 'Transport users', 'Students', 'Everyone')), issued_by VARCHAR(60) NOT NULL, circ_date DATE NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft', 'Published', 'Archived')), template_key VARCHAR(30), body TEXT NOT NULL DEFAULT '', UNIQUE (institution_id, code));
CREATE TABLE public.comm_announcements (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, audience VARCHAR(12) NOT NULL CHECK (audience IN ('Everyone', 'Students', 'Staff', 'Parents')), channels VARCHAR(20) NOT NULL, send_on DATE NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Scheduled' CHECK (status IN ('Draft', 'Scheduled', 'Rejected')));
CREATE TABLE public.comm_notices (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, audience VARCHAR(10) NOT NULL CHECK (audience IN ('Student', 'Staff', 'Parent')), posted_by VARCHAR(60) NOT NULL, posted_on DATE NOT NULL DEFAULT CURRENT_DATE, expires_on DATE NOT NULL);
CREATE TABLE public.comm_templates (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, channel VARCHAR(10) NOT NULL CHECK (channel IN ('Email', 'SMS', 'WhatsApp', 'In-App')), variables VARCHAR(120) NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft', 'Pending approval', 'Approved')), UNIQUE (institution_id, name));
CREATE SEQUENCE public.comm_msg_seq START 77121;
CREATE TABLE public.comm_messages (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, ref VARCHAR(12) NOT NULL DEFAULT ('MSG-' || nextval('public.comm_msg_seq')::text), channel VARCHAR(10) NOT NULL CHECK (channel IN ('Email', 'SMS', 'WhatsApp', 'In-App')), title VARCHAR(160) NOT NULL, subject VARCHAR(160) NOT NULL DEFAULT '', message TEXT NOT NULL, template_id UUID REFERENCES public.comm_templates(id) ON DELETE SET NULL, audience VARCHAR(12) NOT NULL, class_label VARCHAR(40) NOT NULL DEFAULT 'All classes', recipients INTEGER NOT NULL DEFAULT 0, send_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(10) NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'Scheduled', 'Delivered', 'Failed')), copy_to_me BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX comm_messages_inst ON public.comm_messages (institution_id, channel);
ALTER TABLE public.comm_circulars ENABLE ROW LEVEL SECURITY; ALTER TABLE public.comm_announcements ENABLE ROW LEVEL SECURITY; ALTER TABLE public.comm_notices ENABLE ROW LEVEL SECURITY; ALTER TABLE public.comm_templates ENABLE ROW LEVEL SECURITY; ALTER TABLE public.comm_messages ENABLE ROW LEVEL SECURITY;
